            const player = document.getElementById('music-player-1');
            if (!player) return;
            const audio = player.querySelector('.audio-player');
            const btn = player.querySelector('.play-pause-btn');
            const fill = player.querySelector('.progress-bar-fill');
            const wrapper = player.querySelector('.progress-bar-wrapper');
            const currentEl = player.querySelector('.current-time');
            const totalEl = player.querySelector('.total-duration');
            const format = s => {if(isNaN(s)) return '0:00'; const m=Math.floor(s/60),r=Math.floor(s%60); return `${m}:${r.toString().padStart(2,'0')}`;};
            const toggle = () => { if(audio.paused) audio.play(); else audio.pause(); };
            const updateUI = () => {
                if(audio.paused) player.classList.remove('playing');
                else player.classList.add('playing');
            }
            btn.addEventListener('click', toggle);
            audio.addEventListener('play', updateUI);
            audio.addEventListener('pause', updateUI);
            audio.addEventListener('timeupdate', () => {if(audio.duration) fill.style.width=`${(audio.currentTime/audio.duration)*100}%`; currentEl.textContent=format(audio.currentTime);});
            const setDur = () => {if(audio.duration) totalEl.textContent=format(audio.duration);};
            audio.addEventListener('loadedmetadata', setDur);
            if (audio.readyState >= 1) setDur();
            wrapper.addEventListener('click', e => {if(audio.duration) audio.currentTime=(e.offsetX/wrapper.clientWidth)*audio.duration;});

            // Attempt to play on load and handle browser restrictions
            document.addEventListener('DOMContentLoaded', () => {
                let playPromise = audio.play();
                if (playPromise !== undefined) {
                    playPromise.then(_ => {
                        updateUI();
                    }).catch(error => {
                        updateUI();
                        console.log("Autoplay was prevented. Waiting for user interaction.");
                        // Set up a one-time interaction listener to try again
                        const interactionListener = () => {
                            audio.play();
                            document.body.removeEventListener('click', interactionListener);
                            document.body.removeEventListener('wheel', interactionListener);
                            document.body.removeEventListener('touchstart', interactionListener);
                        };
                        document.body.addEventListener('click', interactionListener, {once: true});
                        document.body.addEventListener('wheel', interactionListener, {once: true, passive: true});
                        document.body.addEventListener('touchstart', interactionListener, {once: true, passive: true});
                    });
                }
            });
        })();
    </script>
</body>
