            border-color: var(--focus-color);
            box-shadow: 0 0 8px rgba(234, 192, 134, 0.3);
        }
        textarea:disabled, input:disabled {
            opacity: 0.5;
            cursor: not-allowed;
            background-color: #2a2826;
        }

        .radio-options, .checkbox-options {
            display: flex;
            flex-direction: column;
            gap: 1rem;
            margin-top: 0.5rem;
        }

        .option-label {
            display: flex;
            align-items: center;
            cursor: pointer;
            padding: 0.75rem 1rem;
            background-color: var(--input-bg);
            border-radius: 4px;
            border: 1px solid var(--input-border);
            transition: border-color 0.2s, background-color 0.2s;
        }
        .option-label:hover { background-color: rgba(255,255,255,0.03); }

        .option-label input[type="radio"], .option-label input[type="checkbox"] { display: none; }

        .custom-dot, .custom-checkbox {
            height: 20px;
            width: 20px;
            border: 2px solid var(--text-color);
            border-radius: 50%;
            margin-right: 12px;
            display: flex;
            justify-content: center;
            align-items: center;
            transition: border-color 0.2s;
            flex-shrink: 0;
        }
        .custom-checkbox { border-radius: 4px; }

        .custom-dot::after, .custom-checkbox::after {
            content: '';
            display: block;
            background-color: var(--accent-color);
            transform: scale(0);
            transition: transform 0.2s ease-in-out;
        }
        .custom-dot::after { height: 10px; width: 10px; border-radius: 50%; }
        .custom-checkbox::after { height: 10px; width: 10px; clip-path: polygon(14% 44%, 0 65%, 50% 100%, 100% 15%, 80% 0%, 43% 62%);}

        input[type="radio"]:checked + .custom-dot, input[type="checkbox"]:checked + .custom-checkbox { border-color: var(--accent-color); }
        input[type="radio"]:checked + .custom-dot::after, input[type="checkbox"]:checked + .custom-checkbox::after { transform: scale(1); }

        .custom-input-container { display: flex; align-items: center; gap: 10px; flex-grow: 1; }

        .form-footer { margin-top: 2.5rem; text-align: center; }
        .confirm-button {
            background: linear-gradient(145deg, var(--btn-bg-start), var(--btn-bg-end));
            border: none;
            border-radius: 8px;
            color: var(--btn-text-color);
            padding: 0.8rem 2.5rem;
            font-family: inherit;
            font-size: 1.1rem;
            font-weight: 700;
            cursor: pointer;
            transition: all 0.3s ease;
            box-shadow: 0 4px 10px rgba(0, 0, 0, 0.4);
        }
        .confirm-button:hover { transform: translateY(-2px); box-shadow: 0 6px 15px rgba(0, 0, 0, 0.5); }
        .confirm-button:active { transform: translateY(0); box-shadow: 0 2px 5px rgba(0, 0, 0, 0.4); }

    </style>
</head>
<body>

<div class="creation-form-container">
    <h1 class="main-title">— 开启你的故事 —</h1>

    <form id="story-setup-form">
        <details open>
            <summary>一、你的身份</summary>
            <div class="form-content">
                <textarea id="user-identity" placeholder="请描述你的身份、背景、性格..."></textarea>
            </div>
        </details>

        <details open>
            <summary>二、与李玄的关系</summary>
            <div class="form-content">
                <div class="radio-options">
                    <label class="option-label"><input type="radio" name="relationship" value="宿敌" checked><span class="custom-dot"></span><span>宿敌 (Nemesis)</span></label>
                    <label class="option-label"><input type="radio" name="relationship" value="盟友"><span class="custom-dot"></span><span>盟友 (Ally)</span></label>
                    <label class="option-label"><input type="radio" name="relationship" value="联姻对象"><span class="custom-dot"></span><span>联姻对象 (Marriage Alliance)</span></label>
                    <label class="option-label">
                        <input type="radio" name="relationship" value="custom" id="custom-relationship-radio"><span class="custom-dot"></span>
                        <div class="custom-input-container"><input type="text" id="custom-relationship-input" placeholder="自定义关系..." disabled></div>
                    </label>
                </div>
            </div>
        </details>

        <details>
            <summary>三、初见场景</summary>
            <div class="form-content">
                <div class="checkbox-options" style="margin-bottom: 1rem;">
                    <label class="option-label">
                        <input type="checkbox" id="ai-generate-encounter" checked>
                        <span class="custom-checkbox"></span>
                        <span>由AI生成初见场景</span>
                    </label>
                </div>
                <textarea id="encounter-scene" placeholder="若不希望AI生成，请取消勾选并在此描述你与李玄初次相遇的场景..." disabled></textarea>
            </div>
        </details>

        <details>
            <summary>四、自定义开场白</summary>
            <div class="form-content">
                <div class="checkbox-options" style="margin-bottom: 1rem;">
                    <label class="option-label">
                        <input type="checkbox" id="ai-generate-opening" checked>
                        <span class="custom-checkbox"></span>
                        <span>由AI生成开场剧情</span>
                    </label>
                </div>
                <textarea id="custom-opening" placeholder="你可以在此输入你希望的具体开场剧情，AI将基于此开始故事..." disabled></textarea>
            </div>
        </details>

        <div class="form-footer">
            <button type="button" class="confirm-button" onclick="summarizeAndSend()">确认设定，开始故事</button>
        </div>
    </form>
</div>

<script>
    document.addEventListener('DOMContentLoaded', function() {
        const customRadio = document.getElementById('custom-relationship-radio');
        const customInput = document.getElementById('custom-relationship-input');
        const relationshipRadios = document.querySelectorAll('input[name="relationship"]');

        const aiEncounterCheckbox = document.getElementById('ai-generate-encounter');
        const encounterTextarea = document.getElementById('encounter-scene');
        const aiOpeningCheckbox = document.getElementById('ai-generate-opening');
        const openingTextarea = document.getElementById('custom-opening');

        relationshipRadios.forEach(radio => {
            radio.addEventListener('change', function() {
                customInput.disabled = !customRadio.checked;
                if (customRadio.checked) { customInput.focus(); }
            });
        });

        function setupOptionalField(checkbox, textarea) {
            checkbox.addEventListener('change', function() {
                textarea.disabled = this.checked;
            });
        }
        setupOptionalField(aiEncounterCheckbox, encounterTextarea);
        setupOptionalField(aiOpeningCheckbox, openingTextarea);
    });

    function summarizeAndSend() {
        // --- 1. 获取所有表单数据 ---
        const userIdentity = document.getElementById('user-identity').value.trim();

        let relationshipValue = document.querySelector('input[name="relationship"]:checked').value;
        if (relationshipValue === 'custom') {
            relationshipValue = document.getElementById('custom-relationship-input').value.trim() || '自定义关系（未填写）';
        }

        const isAiEncounter = document.getElementById('ai-generate-encounter').checked;
        const encounterScene = isAiEncounter ? '由AI生成' : document.getElementById('encounter-scene').value.trim();

        const isAiOpening = document.getElementById('ai-generate-opening').checked;
        const customOpening = isAiOpening ? '由AI生成' : document.getElementById('custom-opening').value.trim();

        // --- 2. 构建设定总结文本 ---
        let summary = "--- 自定义开场设定 ---\n";
        summary += `【我的身份】: ${userIdentity || '（未填写）'}\n`;
        summary += `【与李玄的关系】: ${relationshipValue}\n`;
        summary += `【初见场景】: ${encounterScene || '（未填写，由AI生成）'}\n`;
        summary += `【开场剧情】: ${customOpening || '（未填写，由AI生成）'}`;

        // --- 3. 发送消息 ---
        if (!userIdentity) {
            alert('请至少填写您的身份信息！');
            return;
        }

        // 检查环境中是否存在 triggerSlash 函数 (通常由SillyTavern等扩展提供)
        if (typeof triggerSlash === 'function') {
            // 如果存在，则使用该函数直接发送消息
            triggerSlash(`/send ${summary}|/trigger`);
        } else {
            // 如果不存在，则回退到复制到剪贴板或提示用户手动复制
            navigator.clipboard.writeText(summary).then(() => {
                alert('设定已复制到剪贴板！请手动粘贴并发送。');
            }).catch(() => {
                prompt('自动复制失败，请手动复制以下设定内容：', summary);
            });
        }
    }
</script>

</body>
</html>
